// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/// @notice Minimal paymaster-style contract to hold user stablecoin deposits.
/// A trusted relayer (or an admin-controlled owner) calls claimForRelay to collect stable fees.
/// This scaffold is designed for dev/testing. Do not use in production without audits.
contract TokenPaymaster is Ownable {
    IERC20 public immutable stable;
    mapping(address => uint256) public deposits;

    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event RelayerWithdraw(address indexed relayer, uint256 amount);

    constructor(address _stable) {
        require(_stable != address(0), "zero address");
        stable = IERC20(_stable);
    }

    /// @notice Deposit stable tokens into the contract
    function deposit(uint256 amount) external {
        require(amount > 0, "zero amount");
        require(stable.transferFrom(msg.sender, address(this), amount), "transfer failed");
        deposits[msg.sender] += amount;
        emit Deposited(msg.sender, amount);
    }

    /// @notice Withdraw remaining deposit
    function withdraw(uint256 amount) external {
        require(deposits[msg.sender] >= amount, "insufficient");
        deposits[msg.sender] -= amount;
        require(stable.transfer(msg.sender, amount), "transfer failed");
        emit Withdrawn(msg.sender, amount);
    }

    /// @notice Owner (or a designated relayer key) calls to transfer stable fee to relayer.
    /// In a real flow, this should be guarded by signatures / permits / on-chain checks.
    function claimForRelay(address user, address relayer, uint256 amount) external onlyOwner {
        require(deposits[user] >= amount, "insufficient user deposit");
        deposits[user] -= amount;
        require(stable.transfer(relayer, amount), "transfer failed");
        emit RelayerWithdraw(relayer, amount);
    }

    /// @notice Admin sweep for tests
    function adminSweep(address token, address to, uint256 amount) external onlyOwner {
        IERC20(token).transfer(to, amount);
    }
}
// ...existing code...`

`// ...existing code...
import express from "express";
import bodyParser from "body-parser";
import { ethers } from "ethers";
import dotenv from "dotenv";
dotenv.config();

const app = express();
app.use(bodyParser.json());

const PAYMASTER_ABI = [
  "function claimForRelay(address user, address relayer, uint256 amount) external"
];

const L2_RPC = process.env.L2_RPC || "http://localhost:8547";
const PAYMASTER_ADDR = process.env.PAYMASTER_ADDR || "";
const RELAYER_PK = process.env.RELAYER_PK || "";

if (!PAYMASTER_ADDR || !RELAYER_PK) {
  console.error("Set PAYMASTER_ADDR and RELAYER_PK in env");
  process.exit(1);
}

const provider = new ethers.providers.JsonRpcProvider(L2_RPC);
const relayerWallet = new ethers.Wallet(RELAYER_PK, provider);
const paymaster = new ethers.Contract(PAYMASTER_ADDR, PAYMASTER_ABI, relayerWallet);

/*
POST /relay
body: { user: string, to: string, data: string, gasLimit?: number, stableAmount: string }
Notes:
- This example assumes relayer wallet is also the Paymaster owner (for simplicity).
- In production use signed intents and strict authorization.
*/
app.post("/relay", async (req, res) => {
  try {
    const { user, to, data, gasLimit = 200000, stableAmount } = req.body;
    if (!user || !to || !stableAmount) return res.status(400).send("invalid payload");

    // 1) Claim stable from user's deposit (paymaster.owner must be relayer here)
    const claimTx = await paymaster.claimForRelay(user, relayerWallet.address, ethers.BigNumber.from(stableAmount));
    await claimTx.wait();

    // 2) Submit the user's desired transaction on L2 (relayer pays ETH)
    const tx = await relayerWallet.sendTransaction({
      to,
      data,
      gasLimit
    });
    const receipt = await tx.wait();
    return res.json({ receipt });
  } catch (err: any) {
    console.error(err);
    return res.status(500).send(err.message || "error");
  }
});

const PORT = process.env.PORT || 3001;
app.listen(PORT, () => console.log(`Relayer listening on ${PORT}`));
// ...existing code...`

